            'enabled'  => false,
            'log'      => true,
            'commands' => [
                'pull'        => '/usr/bin/git pull',
                'last_commit' => '/usr/bin/git log --name-status HEAD^..HEAD',
            ],
            'keys'     => array_map(function(): string
            {
                return password(len: 128, useSpecials: false);
            }, array_fill(0, 8, null)),
        ],
    ];
});

