listen('init', function(): void
{
    register_task(
        bundle: 'core',
        name:   'sitemap_generate',
        args:   [ 'src' => [ 'desc' => "Source Name", 'optional' => true ] ],
        func:   function(string $ctx, object $args): void
        {
            generate_sitemap(sourceName: $args->src ?? null);
            json_success();
        },
    );
});

